void insertionSort(int A[], int n, int g, int *cnt) {
    for (int i = g; i < n; i++) {
        int v = A[i];
        int j = i - g;
        while (j >= 0 && A[j] > v) {
            A[j + g] = A[j];
            j -= g;
            (*cnt)++;
        }
        A[j + g] = v;
    }
}

void shellSort(int A[], int n) {
    int cnt = 0;
    int m = 0;
    int G[100];  // enough for n up to 1,000,000

    // Generate gap sequence: powers of 2 minus 1
    int g = 1;
    while (g <= n) {
        G[m++] = g;
        g = 2 * g + 1;
    }

    // Output number of gaps
    printf("%d\n", m);

    // Output gap values in decreasing order
    for (int i = m - 1; i >= 0; i--) {
        if (i != m - 1) printf(" ");
        printf("%d", G[i]);
    }
    printf("\n");

    // Perform shell sort with gaps in decreasing order
    for (int i = m - 1; i >= 0; i--) {
        insertionSort(A, n, G[i], &cnt);
    }

    // Output count of operations
    printf("%d\n", cnt);

    // Output sorted array
    for (int i = 0; i < n; i++) {
        printf("%d\n", A[i]);
    }
}

