int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    // Generate gap sequence: 1, 4, 13, 40, 121, ... (3*h + 1)
    vector<int> gaps;
    int h = 1;
    while (h <= n) {
        gaps.push_back(h);
        h = 3 * h + 1;
    }
    reverse(gaps.begin(), gaps.end()); // decreasing order for Shell Sort

    int cnt = 0;

    for (int g : gaps) {
        for (int i = g; i < n; i++) {
            int key = a[i];
            int j = i - g;
            while (j >= 0 && a[j] > key) {
                a[j + g] = a[j];
                j -= g;
                cnt++;
            }
            a[j + g] = key;
            if (j >= 0) cnt++; // count the comparison that failed
        }
    }

    // Output
    cout << gaps.size() << "\n";
    for (size_t i = 0; i < gaps.size(); i++) {
        if (i) cout << " ";
        cout << gaps[i];
    }
    cout << "\n";
    cout << cnt << "\n";
    for (int i = 0; i < n; i++) {
        if (i) cout << " ";
        cout << a[i];
    }
    cout << "\n";

    return 0;
}

